arguments.command:
bash -lc 'python - << "PY"
import io,sys
p = "/src/libxml2/xinclude.c"
with open(p, "r") as f:
    s = f.read()
old_block = '''case XML_XINCLUDE_START: {
                        xmlNodePtr tmp, cur = set->nodeTab[i];

                        cur = cur->next;
                        while (cur != NULL) {
                            switch(cur->type) {
                                case XML_TEXT_NODE:
                                case XML_CDATA_SECTION_NODE:
                                case XML_ELEMENT_NODE:
                                case XML_ENTITY_REF_NODE:
                                case XML_ENTITY_NODE:
                                case XML_PI_NODE:
                                case XML_COMMENT_NODE:
                                    tmp = xmlXIncludeCopyNode(ctxt, target,
                                                          source, cur);
                                    if (last == NULL) {
                                        list = last = tmp;
                                    } else {
                                        last = xmlAddNextSibling(last, tmp);
                                    }
                                    cur = cur->next;
                                    continue;
                                default:
                                    break;
                            }
                            break;
                        }
                        continue;
                    }'''
new_block = '''case XML_XINCLUDE_START: {
                        xmlNodePtr tmp, cur = set->nodeTab[i];

                        cur = cur->next;
                        while (cur != NULL) {
                            xmlNodePtr nextCur = cur->next;
                            switch(cur->type) {
                                case XML_TEXT_NODE:
                                case XML_CDATA_SECTION_NODE:
                                case XML_ELEMENT_NODE:
                                case XML_ENTITY_REF_NODE:
                                case XML_ENTITY_NODE:
                                case XML_PI_NODE:
                                case XML_COMMENT_NODE:
                                    tmp = xmlXIncludeCopyNode(ctxt, target,
                                                          source, cur);
                                    if (last == NULL) {
                                        list = last = tmp;
                                    } else {
                                        last = xmlAddNextSibling(last, tmp);
                                    }
                                    cur = nextCur;
                                    continue;
                                default:
                                    break;
                            }
                            break;
                        }
                        continue;
                    }'''
if old_block in s:
    s = s.replace(old_block, new_block)
    with open(p, 'w') as f:
        f.write(s)
    print('patched')
else:
    print('block not found, no patch applied')
PY'
